    ('e0a03a95-5347-5591-a4a4-0c9d32beddbb'::uuid, '87281abc-c367-53fd-b702-384b83db3b01'::uuid, 'Qu’est-ce que la Maison de la Sagesse ?', 'mcq', '["Un centre de traduction et de savoir à Bagdad","Une mosquée de La Mecque","Un palais califal de Damas","Une école coranique de Cordoue"]'::jsonb, 0, 'Elle transmet les savoirs grecs, perses et indiens.', 6),
    ('cdf00ce9-dfdb-593e-b19b-52edda73bf8e'::uuid, '87281abc-c367-53fd-b702-384b83db3b01'::uuid, 'Qui sont les dhimmis ?', 'mcq', '["Les chrétiens et les juifs, qui gardent leur religion contre un impôt","Les esclaves de l’empire","Les soldats du calife","Les marchands étrangers"]'::jsonb, 0, 'Un statut inférieur mais protégé.', 7),
    ('651c59d7-ac9e-5f0a-9d40-eeb5a1e0180d'::uuid, '87281abc-c367-53fd-b702-384b83db3b01'::uuid, 'L’empire musulman s’est constitué en plusieurs siècles.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’essentiel des conquêtes tient en un siècle, de 632 à 750.', 8),
    ('91e1fd34-a246-559f-af3a-c8dae7590b8c'::uuid, 'e162bc68-b2d4-508f-a006-ec5ae979bf05'::uuid, 'Quelle est la capitale de l’Empire byzantin ?', 'mcq', '["Constantinople","Rome","Athènes","Damas"]'::jsonb, 0, 'L’ancienne Byzance, l’actuelle Istanbul.', 1),
